"""Academy Year 8 revision set 1: eight sheets. Writes academy/<code>.json (then academy_sheet.py, topdf.js)."""
import json, pathlib
x, y, a, b, c, m, n, p, q = ('<i>x</i>', '<i>y</i>', '<i>a</i>', '<i>b</i>', '<i>c</i>', '<i>m</i>', '<i>n</i>', '<i>p</i>', '<i>q</i>')
def F(nu, de): return f'<span class="frac"><span class="nu">{nu}</span><span class="de">{de}</span></span>'
def M(w, nu, de): return f'{w}{F(nu, de)}'
NEXT = {"title": "Keep going in the Maths Forensics Academy", "text": "Step-by-step lessons, answers checked as you go, story cases and maths games for Years 7 to 9. Try the free topics.", "url": "https://www.mathsforensics.com/academy"}
LONG = ["Getting the basics: one step at a time.", "Year 8 standard: a few steps, some in context.", "A stretch: problems, reasoning and spotting mistakes."]
def Q(text, ans, work=None, lines=2, label="Answer", tip=None, tampered=None):
    d = {"text": text if isinstance(text, list) else [text], "answer": ans, "lines": lines, "answer_label": label}
    for k, v in (("working", work), ("tip", tip), ("tampered", tampered)):
        if v: d[k] = v
    return d
def sheet(code, strand, title, cover, listen, brief, method, examples, d, s, e, mistakes, closed):
    return {"code": code, "product_line": "Academy worksheet · Year 8 · Free", "strand": strand, "title": title,
            "level_line": "Year 8 · KS3", "time": "About 40 minutes", "cover_sub": cover, "parents": {"listen": listen},
            "levels_long": dict(zip("dse", LONG)), "briefing": brief, "method": method, "examples": examples,
            "sections": {"d": {"blurb": "Warm up. One step at a time.", "questions": d},
                         "s": {"blurb": "The Year 8 standard. Show each step.", "questions": s},
                         "e": {"blurb": "Problems, reasoning and one piece of tampered evidence.", "questions": e}},
            "mistakes": mistakes, "closed_title": title, "closed_points": closed, "next": NEXT}

